contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: initialMin - value to set initially; newMin - value attempted after Initialized
    function run(uint initialMin, uint newMin) public {
        // 1) Before initialization, set MinSum to initialMin
        c.SetMinSum(initialMin);

        // 2) Mark contract initialized
        c.Initialized();

        // 3) Attempt to set MinSum again after initialization. On P this should revert.
        // We capture whether it reverted by using a low-level call.
        (bool success, ) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", newMin));

        // Observe current MinSum via public getter
        uint cur = c.MinSum();

        // Rule: if contract enforces the initialization guard then the second SetMinSum call must have reverted
        // and current MinSum must still equal the initial value. This holds for P and is violated by M.
        assert(!success && cur == initialMin);
    }

    // allow this test contract to hold ETH if needed by caller (not required here)
    receive() external payable {}
}

